css:
/* Safe CSS - No Zoom */
.print-format {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif !important;
    font-size: 10px !important; /* Smaller font naturally */
    line-height: 1.2 !important;
}

/* Zero-Space Section Breaks */
.section-break {
    padding: 2px 0 !important;
    border-top: 1px solid #eee !important;
}

/* Tight Tables */
.print-format table {
    width: 100% !important;
    border-collapse: collapse !important;
    margin-bottom: 5px !important;
}

.print-format th {
    background-color: #f0f4f7 !important;
    padding: 3px 5px !important;
    border-bottom: 1px solid #ccc !important;
    font-size: 9px !important; /* Smaller headers */
}

.print-format td {
    padding: 3px 5px !important;
    border-bottom: 1px solid #eee !important;
}

/* Align Money Right */
.print-format td:nth-child(2), 
.print-format th:nth-child(2) {
    text-align: right !important;
}

/* Hide Footers */
.print-heading-template, .print-footer, .print-format-footer {
    display: none !important;
}

/* Force Single Page */
html, body, tr, td, div {
    page-break-inside: avoid !important;
}
